import * as THREE from "three";
import { Hypercube } from "..";

export class SolarPanel {
  public hypercube: Hypercube;
  public meshGroup: THREE.Group;
  public pivot: THREE.Object3D;

  constructor(hypercube: Hypercube, meshGroup: THREE.Group) {
    this.hypercube = hypercube;
    this.meshGroup = meshGroup;

    const pivotPos = new THREE.Vector3(0, -15, 17);

    // 1. 피벗 생성하고 원하는 위치 지정
    const pivot = new THREE.Object3D();
    pivot.position.copy(pivotPos);
    this.pivot = pivot;

    // 2. 메쉬를 피벗 기준으로 이동 (상대 좌표)
    this.meshGroup.position.sub(pivotPos); // 피벗 위치만큼 빼줌
    pivot.add(this.meshGroup); // 피벗에 메쉬 추가

    // 3. 씬에 피벗 추가
    this.hypercube.core.scene.add(pivot);

    // 4. 피벗 시각화를 위한 작은 구체 추가
    const pivotMarker = new THREE.Mesh(
      new THREE.SphereGeometry(0.001, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0xff0000 })
    );
    pivotMarker.position.set(0, 0, 0); // 피벗의 로컬 중심에
    pivot.add(pivotMarker);

    const offset = 0.04;
    this.pivot.rotation.x = offset - Math.PI * 0.25 * 0.25 * 0.75;
  }

  public rotate(v: number) {
    const offset = 0.04;
    this.pivot.rotation.x = offset + (v - Math.PI * 0.25 * 0.25 * 0.75);
  }

  public update() {
    // 추후 업데이트용
  }
}
